  // state: Control (CEN/prefetch/ECC/RAM timing), HPM Control, Way Allocation
  // Masks. The read-only Configuration Register, the side-effecting CCTL command
  // registers (writing one re-issues an L2 cache op), and the write-1-clear
  // error registers are captured in the record but NEVER written back.
  //
  // Hard-gated on the engine having an L2C (l2c_present_): a store to an absent
  // L2C region faults the Program Buffer, so unlike a tolerant CSR write this
  // must issue nothing on a core without an L2C. x5/x6 are safe scratch here --
  // the caller runs this before the GPR loop, which overwrites both.
  void restore_l2c(const hybrid_state_v1& state)
  {
    if (!(state.flags & HYBRID_FLAG_L2C)) return;
    if (!l2c_present_) return;

    // Control is a read-MERGE-write, not a raw store: only the policy bits
    // [7:0] (CEN, PFTHRES, IPFDPT, DPFDPT, ECCEN) are the producer's to
    // restore. The bits above belong to this RTL -- the RAM-timing fields
    // [13:8] reset from the hardware build config (a QEMU producer models
    // the block as a zero-filled RAM stub, so a raw store would zero them
    // and detune the live cache RAMs), INITSTATUS[14]/COHSTA are read-only
    // status. DS220 11.8.7 / DS295 11.7.7.
    const uint64_t live = pb_load_l2c_reg(HYBRID_L2C_OFF_CONTROL);
    pb_store_l2c_reg(HYBRID_L2C_OFF_CONTROL,
                     (live & ~uint64_t{HYBRID_L2C_CTRL_POLICY_MASK})
                       | (state.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8]
                          & HYBRID_L2C_CTRL_POLICY_MASK));
    pb_store_l2c_reg(HYBRID_L2C_OFF_HPM_CTL0,
                     state.l2c.reg[HYBRID_L2C_OFF_HPM_CTL0 / 8]);
    for (uint32_t i = 0; i < HYBRID_L2C_WAYMASK_NUM; ++i) {
      const uint32_t off = HYBRID_L2C_OFF_WAYMASK0 + i * 8u;
      pb_store_l2c_reg(off, state.l2c.reg[off / 8]);
    }
  }

  // One L2C register read-back: stage the MMIO address in x6, execute
  // `lwu x5, 0(x6)` in the Program Buffer, then read x5 -- the dual of
  // pb_store_l2c_reg and the same sequence StateDrain uses at the exit.
  // Feeds the Control merge; x5/x6 are pre-GPR-loop scratch here too.
  auto pb_load_l2c_reg(uint32_t offset) -> uint64_t
  {
    write_register_abstract(bus_, regno_gpr(6), l2c_base_ + offset);
    const std::array<uint32_t, 1> pb = { encode_lwu(5, 6, 0) };
    exec_progbuf(bus_, std::span<const uint32_t>{pb});
    return read_register_64(bus_, regno_gpr(5), "ResumeDriver L2C read-back");
  }

  // One L2C register store: stage the MMIO address in x6 and the value's low
  // word in x5, then execute `sw x5, 0(x6)` in the Program Buffer. Word store
  // per DS220 11.8.3 (single transfer, access size < 8 bytes); all documented
  // L2C control bits live in the low 32.
  void pb_store_l2c_reg(uint32_t offset, uint64_t value)
  {
    write_register_abstract(bus_, regno_gpr(6), l2c_base_ + offset);
    write_register_abstract(bus_, regno_gpr(5), value & 0xffffffffu);
    const std::array<uint32_t, 1> pb = { encode_sw(5, 6, 0) };
    if (oplog_)
      oplog_->record(OpLog::Kind::ProgBuf, static_cast<uint16_t>(offset),
                     pb[0]);
    exec_progbuf(bus_, std::span<const uint32_t>{pb});
  }

  // Andes V5 + M-ext CSR restore: one caps-gated abstract write per CSR
  // (pmaaddr before pmacfg, mirroring the PMP restore ordering), each gated by
  // the LG1 reset baseline. Abstract-only by design -- a batched Program-Buffer
  // sweep can't tolerate a cmderr on one CSR without corrupting the rest of the
  // batch (a WARL/read-only CSR faults the whole group mid-sweep), whereas the
  // per-CSR abstract path tolerates a single failure and moves on.
  void restore_andes_m_ext(const hybrid_state_v1& state)
  {
    const bool andes = state.flags & HYBRID_FLAG_ANDES;
    const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
    if (!andes && !mext) return;

    // Each write is double-gated: caps (the ENGINE implements the CSR) and the
    // v6 write-mask (the PRODUCER's guest actually wrote it -- wm_live).
    if (andes) {
#define X(field, addr, name)                                                  \
  if (caps_.supports_csr(addr)                                                \
      && wm_live(state, HYBRID_WM_ANDES_BASE + HYBRID_WM_ANDES_IDX_##field))  \
    write_csr_tolerant_gated(addr, state.andes.field, baseline_.andes.field);
      HYBRID_ANDES_CSR_LIST(X)

