// Every mcache_ctl write-command's 64-bit DATA payload, in issue order.
static auto mcache_ctl_write_values(const RecordingBus& bus)
  -> std::vector<uint64_t>
{
  std::vector<uint64_t> vals;
  for (std::size_t i = 2; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && (op.value & 0xFFFFu) == hybrid::regno_csr(0x7CA)
        && ((op.value >> 16) & 1u)) {
      const auto& d0 = bus.ops[i - 2];
      const auto& d1 = bus.ops[i - 1];
      REQUIRE(d0.reg == kData0);
      REQUIRE(d1.reg == kData1);
      vals.push_back(uint64_t(d0.value) | (uint64_t(d1.value) << 32));
    }
  }
  return vals;
}

TEST_CASE("Andes cache fix: a both-caches enable is staged IC-first -- two "
          "mcache_ctl writes (value sans DC_EN, then the full value)")
{
  // One halted-mode abstract write that flips IC_EN AND DC_EN together
  // wedges the uncached/device path on coherence-manager RTL builds
  // (ax46mpv_fpga_l3, NDS_CACHE_COHERENCE_SUPPORT=1): every later device
  // load reads 0 and UART stores are dropped, while either enable alone is
  // fine. Mirror the producer's own sequence (crt0 sets IC first, then
  // csrw's the full value): stage the value with DC_EN clear, then write
  // the drained value. Semantically a no-op on every other engine.
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.mcache_ctl = 0x703ULL;  // both enables + prefetch, from a reset-0 baseline

  hybrid::ResumeDriver driver(bus, kScratch);
  driver.resume(s);

  const auto vals = mcache_ctl_write_values(bus);
  REQUIRE(vals.size() == 2);
  CHECK(vals[0] == 0x701ULL);  // stage: everything but DC_EN
  CHECK(vals[1] == 0x703ULL);  // final: the drained value
}

