// csrrw), not as a DM abstract register write: on coherence-manager RTL
// builds (ax46mpv_fpga_l3, NDS_CACHE_COHERENCE_SUPPORT=1) an abstract
// write that leaves BOTH L1 enables set wedges the uncached/device access
// path -- every later device load returns 0 and UART stores are dropped,
// while the same value written by an executed csrw (what crt0 itself
// does) is fine. Runs before the GPR loop: the PB stages the value in
// scratch x5, which the loop below overwrites with its architectural
// value. Tolerant like every Andes CSR write: on a core without the CSR
// the PB faults, and clear_cmderr_if_set() swallows it.
if (wm_live(state, HYBRID_WM_MCACHE_CTL)
    && !baseline_skips(state.mcache_ctl, baseline_.mcache_ctl)) {
  write_64bit_register(regno_gpr(5), state.mcache_ctl);
  const std::array<uint32_t, 1> pb = {
    encode_csrrw(0, kCsrMcacheCtl, 5)
  };
  if (oplog_)
    oplog_->record(OpLog::Kind::ProgBuf, regno_csr(kCsrMcacheCtl), pb[0]);
  exec_progbuf(bus_, std::span<const uint32_t>{pb});
  clear_cmderr_if_set();
}

