// Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
// functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
// caches) but has no cache model, so without this the cycle engine resumes
// at the ROI with caches at their reset default -- DISABLED -- and the
// whole measured window runs uncached, inflating it severalfold. Tolerant
// writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
// write as a no-op, and a drained 0 (caches were off) restores the reset
// state, so this is always safe to issue.
//
// A restore that flips IC_EN and DC_EN together is staged IC-first: one
// halted-mode abstract write enabling BOTH L1 caches at once wedges the
// uncached/device access path on coherence-manager RTL builds
// (ax46mpv_fpga_l3, NDS_CACHE_COHERENCE_SUPPORT=1) -- every later device
// load returns 0 and UART stores are dropped, while either enable alone
// is fine. Mirroring the producer's own sequence (crt0 sets IC_EN first,
// then csrw's the full value) is a semantic no-op on every other engine:
// the final value is identical.
if (wm_live(state, HYBRID_WM_MCACHE_CTL)
    && !baseline_skips(state.mcache_ctl, baseline_.mcache_ctl)) {
  constexpr uint64_t kIcEn = 1u << 0, kDcEn = 1u << 1;
  const bool flips_both = (state.mcache_ctl & kIcEn)
                       && (state.mcache_ctl & kDcEn)
                       && !(baseline_.mcache_ctl & kIcEn)
                       && !(baseline_.mcache_ctl & kDcEn);
  if (flips_both)
    write_csr_tolerant(kCsrMcacheCtl, state.mcache_ctl & ~kDcEn);
  write_csr_tolerant(kCsrMcacheCtl, state.mcache_ctl);
}
if (wm_live(state, HYBRID_WM_MMISC_CTL))
  write_csr_tolerant_gated(kCsrMmiscCtl,  state.mmisc_ctl,
                           baseline_.mmisc_ctl);

