          "on the hart pipeline, never as an abstract CSR write")
{
  // A halted-mode ABSTRACT write of mcache_ctl that leaves both L1 enables
  // set wedges the uncached/device access path on coherence-manager RTL
  // builds (ax46mpv_fpga_l3, NDS_CACHE_COHERENCE_SUPPORT=1): every later
  // device load reads 0 and UART stores are dropped. The same value written
  // by an EXECUTED csrw (what crt0 itself does on a running hart) is fine,
  // so the restore stages the value in scratch x5 and executes
  // `csrrw x0, mcache_ctl, x5` in the Program Buffer.
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.mcache_ctl = 0x703ULL;  // crt0's I-cache + D-cache + prefetch enable

  hybrid::ResumeDriver driver(bus, kScratch);
  driver.resume(s);

  // No abstract write-command may target 0x7CA...
  CHECK(mcache_ctl_write_values(bus).empty());

  // ...instead the PB carries `csrrw x0, 0x7CA, x5`, an exec fires, and some
  // abstract GPR-x5 write staged the drained value first.
  const uint32_t want_pb = hybrid::encode_csrrw(0, 0x7CA, 5);
  bool found_pb = false, found_exec = false, staged_x5 = false;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind != DmiOp::Kind::Write) continue;
    if (op.reg == hybrid::kProgbuf0 && op.value == want_pb) found_pb = true;
    if (op.reg == kCommand && op.value == hybrid::kExecProgbufCmd)
      found_exec = true;
    if (op.reg == kCommand && (op.value & 0xFFFFu) == hybrid::regno_gpr(5)
        && ((op.value >> 16) & 1u) && i >= 2
        && bus.ops[i - 2].reg == kData0
        && bus.ops[i - 2].value == 0x703u)
      staged_x5 = true;
  }
  CHECK(found_pb);
  CHECK(found_exec);
  CHECK(staged_x5);
}

